func (s *PayrollDispatch) Overview(ctx context.Context) (workforce.PayrollDispatchOverview, error) {
	latest, err := s.deps.Store.LatestPayrollDispatch(ctx)
	if err != nil || latest == nil {
		return workforce.PayrollDispatchOverview{}, err
	}
	view := workforce.PayrollDispatchView{Year: latest.Year, Month: latest.Month, Correction: latest.Sequence > 0, Channel: latest.Channel, Format: latest.Format, Recipient: latest.Recipient, State: latest.State, Reason: latest.Reason, Attempts: latest.Attempts, Filename: latest.Filename, CreatedAt: latest.CreatedAt, FinishedAt: latest.FinishedAt, DownloadExpiresAt: latest.DownloadExpiresAt, DownloadedAt: latest.DownloadedAt}
	return workforce.PayrollDispatchOverview{Latest: &view}, nil
}

func (s *Service) AllowanceSummary(ctx context.Context, staffID, absenceTypeID int64, year int) (workforce.AbsenceTypeAllowanceSummary, error) {
	if staffID <= 0 || year < 2000 || year > 2100 {
		return allowanceSummaryToPublic(domain.AbsenceTypeAllowanceSummary{}), MapError(domain.ErrAbsenceTypeAllowanceInvalid)
	}
	absenceType, err := s.findAllowanceType(ctx, absenceTypeID)
	if err != nil {
		return allowanceSummaryToPublic(domain.AbsenceTypeAllowanceSummary{}), MapError(err)
	}
	accounts, err := s.loadAllowanceAccounts(ctx, staffID, absenceType, year, year)
	if err != nil {
		return allowanceSummaryToPublic(domain.AbsenceTypeAllowanceSummary{}), MapError(err)
	}
	return allowanceSummaryToPublic(accounts.ledger(s.clock.Today()).Summary(staffID, absenceTypeID, year)), MapError(nil)
}

